function designerGoogleFontLinkId(family: string): string {
  const safe = family.trim().toLowerCase().replace(/[^a-z0-9]+/g, "-").replace(/^-+|-+$/g, "");
  return `fh-gfont-installed-${safe || "custom"}`;
}

type BrainTextBlockKind = "Titular" | "Subtítulo" | "Párrafo" | "CTA" | "Quote";
type TextContentTransformAction = "correct" | "translate";
type TextContentTargetLanguage = "es" | "en" | "ca";

const TEXT_CONTENT_LANGUAGE_OPTIONS: Array<{ value: TextContentTargetLanguage; label: string }> = [
  { value: "es", label: "Español" },
  { value: "en", label: "Inglés" },
  { value: "ca", label: "Catalán" },
];

function inferBrainTextBlockKind(opts: {
  text: string;
  width: number;
  height: number;
  fontSize: number;
}): BrainTextBlockKind {
  const text = (opts.text || "").trim();
  const lines = text.length === 0 ? 1 : text.split(/\r?\n+/).filter(Boolean).length;
  const chars = text.length;
  const ratio = opts.width > 0 ? opts.height / opts.width : 0;
  const isShort = chars <= 44;
  const isVeryShort = chars <= 24;
  const isTall = opts.height >= Math.max(48, opts.fontSize * 2.4);
  const hasQuoteTone = text.startsWith("“") || text.startsWith("\"") || / dijo | afirma | comentó /i.test(text);

  if (hasQuoteTone && chars <= 170) return "Quote";
  if (isVeryShort || lines === 1 && ratio < 0.18) return "Titular";
  if (isShort && (ratio < 0.3 || lines <= 2)) return "Subtítulo";
  if (chars <= 70 && /^(compra|descubre|solicita|empieza|prueba|reserva|únete|ver|leer)\b/i.test(text)) return "CTA";
  if (isTall || lines >= 3 || chars > 140) return "Párrafo";
  return "Subtítulo";
}

function brainAspectRatioForGemini(width: number, height: number): string {
  const ratio = width > 0 && height > 0 ? width / height : 1;
  const options = [
    { id: "1:1", r: 1 },
    { id: "4:3", r: 4 / 3 },
    { id: "3:4", r: 3 / 4 },
    { id: "16:9", r: 16 / 9 },
    { id: "9:16", r: 9 / 16 },
  ];
  let best = options[0]!;
  let bestDist = Math.abs(ratio - best.r);
  for (const opt of options.slice(1)) {
    const d = Math.abs(ratio - opt.r);
    if (d < bestDist) {
      best = opt;
      bestDist = d;
    }
  }
  return best.id;
}

async function rasterizeLogoDataUrlToPng(dataUrl: string, maxSide = 1024): Promise<string | null> {
  if (typeof window === "undefined") return null;
  return await new Promise((resolve) => {
    const img = new Image();
    img.onload = () => {
      try {
        const w0 = Math.max(1, img.naturalWidth || img.width || 1);
        const h0 = Math.max(1, img.naturalHeight || img.height || 1);
        const scale = Math.min(1, maxSide / Math.max(w0, h0));
        const w = Math.max(1, Math.round(w0 * scale));
        const h = Math.max(1, Math.round(h0 * scale));
        const canvas = document.createElement("canvas");
        canvas.width = w;
        canvas.height = h;
        const ctx = canvas.getContext("2d");
        if (!ctx) return resolve(null);
        ctx.clearRect(0, 0, w, h);
        ctx.drawImage(img, 0, 0, w, h);
        resolve(canvas.toDataURL("image/png"));
      } catch {
        resolve(null);
      }
    };
    img.onerror = () => resolve(null);
    img.src = dataUrl;
  });
}

